<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login(true);
$recoveryCodes=$_SESSION['new_mfa_recovery_codes']??null;if(!empty($me['mfa_enabled'])&&!$recoveryCodes){header('Location: '.path('admin/index.php'));exit;}if($recoveryCodes){unset($_SESSION['new_mfa_recovery_codes']);}elseif(empty($_SESSION['mfa_setup_secret']))$_SESSION['mfa_setup_secret']=Security::base32Encode(random_bytes(20));
$secret=(string)($_SESSION['mfa_setup_secret']??'');$error='';
if(!$recoveryCodes&&$_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$code=trim((string)($_POST['code']??''));if(!Security::verifyTotp($secret,$code))$error='Kode ntabwo ihuye. Reba ko isaha ya telefoni iri ku gihe.';else{$encrypted=Security::encrypt($secret,encryption_keys(),active_encryption_key_id());$codes=[];db()->beginTransaction();try{db()->prepare('UPDATE users SET mfa_enabled=1,mfa_secret_encrypted=? WHERE id=?')->execute([$encrypted,(int)$me['id']]);db()->prepare('DELETE FROM mfa_recovery_codes WHERE user_id=?')->execute([(int)$me['id']]);$insert=db()->prepare('INSERT INTO mfa_recovery_codes(user_id,code_hash) VALUES (?,?)');for($i=0;$i<10;$i++){$raw=strtoupper(bin2hex(random_bytes(6)));$codes[]=$raw;$insert->execute([(int)$me['id'],password_hash($raw,PASSWORD_DEFAULT)]);}db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}$_SESSION['user']['mfa_enabled']=true;unset($_SESSION['mfa_setup_secret']);$_SESSION['new_mfa_recovery_codes']=$codes;audit_log('mfa_enabled','user',(int)$me['id']);header('Location: '.path('admin/mfa.php'));exit;}}
$issuer=rawurlencode((string)cfg('mfa_issuer','AFRIVOX NEWS'));$label=rawurlencode('AFRIVOX NEWS:'.$me['email']);$uri="otpauth://totp/$label?secret=$secret&issuer=$issuer&digits=6&period=30";
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shyiraho MFA · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="login-page"><main class="login-panel"><div class="overline">SECURITY REQUIRED</div><?php if($recoveryCodes):?><h1>Bika <em>recovery codes.</em></h1><p>Izi codes zerekanwa rimwe gusa. Zibike ahantu hafunze; buri imwe ikoreshwa rimwe.</p><pre style="white-space:pre-wrap"><?=e(implode("\n",$recoveryCodes))?></pre><p><a class="button-outline" href="<?=e(path('admin/index.php'))?>">KOMEZA MURI NEWSROOM →</a></p><?php else:?><h1>Shyiraho <em>MFA.</em></h1><p>Ongeramo konti muri authenticator ukoresheje secret iri hasi. Ntuyisangize undi.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><p><code><?=e($secret)?></code></p><details><summary>Authenticator URI</summary><code style="overflow-wrap:anywhere"><?=e($uri)?></code></details><form method="post" class="public-form"><?=csrf_field()?><label>KODE Y'IMIBARE 6<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button type="submit">EMEZA MFA →</button></form><?php endif;?></main></body></html>
